<?php
session_start();require 'config.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$username=strtolower(trim($_POST['username']??''));$name=trim($_POST['name']??'');$password=$_POST['password']??'';$role=$_POST['role']??'student';
if($name===''||!preg_match('/^[a-zA-Z0-9_.-]{3,30}$/',$username)||strlen($password)<8||!in_array($role,['student','teacher'],true)){$error='Enter a name, valid username (3–30 characters), and password of at least 8 characters.';}else{try{$stmt=$pdo->prepare('INSERT INTO users(name,username,password_hash,role) VALUES(?,?,?,?)');$stmt->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT),$role]);session_regenerate_id(true);$_SESSION['user_id']=(int)$pdo->lastInsertId();$_SESSION['name']=$name;$_SESSION['role']=$role;header('Location: dashboard.php');exit;}catch(PDOException $e){$error='That username may already be taken. Try another one.';}}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Create account</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-page"><main class="auth-card"><a class="back-link" href="index.php">← Back to login</a><h1>Create account</h1><p class="muted">Set up your student or teacher account.</p><?php if($error):?><div class="alert"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><label for="name">Full name</label><input id="name" name="name" required maxlength="100"><label for="username">Username</label><input id="username" name="username" required minlength="3" maxlength="30"><label for="password">Password (minimum 8 characters)</label><input id="password" name="password" type="password" required minlength="8"><label for="role">Account type</label><select id="role" name="role"><option value="student">Student</option><option value="teacher">Teacher</option></select><button class="button full" type="submit">Create account</button></form></main></body></html>
